"""Generate a trusted offline rating form; package/model text is rendered as text only."""
import base64
import hashlib
import json
from pathlib import Path


def render_form(packets, contexts, dimensions, batch_id):
    payload=json.dumps({'packets':packets,'contexts':contexts,'dimensions':dimensions,'batchId':batch_id},ensure_ascii=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    script=(Path(__file__).with_name('review_form.js')).read_text(encoding='utf-8')
    digest=base64.b64encode(hashlib.sha256(script.encode()).digest()).decode()
    # Only the exact authored script is executable. No fetch, external assets, eval or third-party markup.
    return '''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'sha256-'''+digest+'''\x27; style-src 'unsafe-inline'; connect-src 'none'; img-src 'none'; base-uri 'none'; form-action 'none'">
<title>NutriScan independent response review</title>
<style>body{font:16px/1.55 system-ui,sans-serif;color:#18392c;background:#f6f8f5;margin:0}header,main{max-width:1000px;margin:auto;padding:20px}header{border-bottom:1px solid #ccd7cf}h1{font-size:1.5rem;margin:0}h2{font-size:1.15rem}label{display:block;margin:10px 0}input,select,textarea,button{font:inherit;padding:8px;border:1px solid #9aada0;border-radius:6px;box-sizing:border-box}textarea{width:100%;min-height:70px}button{background:#e1eee4;cursor:pointer;margin:5px}pre{white-space:pre-wrap;overflow-wrap:anywhere;font:inherit}section{background:white;padding:18px;margin:18px 0;border:1px solid #d3ded5;border-radius:10px}fieldset{border:0;padding:8px 0;border-bottom:1px solid #e3e8e3}legend{font-weight:600}#message{min-height:24px}small{display:block}.error{color:#9b231a}.actions{position:sticky;bottom:0;background:#f6f8f5;padding:10px;border-top:1px solid #ccd7cf}select{max-width:100%}input[type=text]{max-width:100%;width:350px}@media(min-width:700px){.review-controls{display:flex;gap:16px;align-items:center;flex-wrap:wrap}}:focus-visible{outline:3px solid #176b47;outline-offset:2px}</style>
<header><h1>NutriScan independent response review</h1><p>Record your own assessment. No model or network request is made. Treat the supplied context as private.</p><small>0 incorrect/unusable · 1 major problems · 2 mixed · 3 mostly correct/useful · 4 fully supported/useful. Leave pending or select N/A with a reason.</small><div class="review-controls"><label>Reviewer code <input id="reviewer" type="text" maxlength="80" placeholder="Pseudonymous code"></label><label><input id="persist" type="checkbox"> Save ratings on this device</label><button id="restore" type="button">Restore saved draft</button><button id="clear" type="button">Remove saved draft</button></div><label>Response <select id="response"></select></label><p id="progress"></p></header>
<main><section><h2>Authorized question and context</h2><pre id="context"></pre></section><section><h2>Response to assess</h2><pre id="answer"></pre><details><summary>Source receipts</summary><pre id="sources"></pre></details></section><section id="rubric"><h2>Your ratings</h2></section><section><label>Evidence pointers and reasons (one per line)<textarea id="evidence"></textarea></label><label>Critical errors (JSON array of responseSpan, evidencePointer and reason)<textarea id="critical">[]</textarea></label><label>Additional comments<textarea id="comments"></textarea></label><label><input type="checkbox" id="human"> These assessments are my own human judgments.</label></section><div class="actions"><button id="previous" type="button">Previous</button><button id="next" type="button">Next</button><button id="export" type="button">Export completed ratings</button><p id="message" role="status" aria-live="polite"></p></div></main>
<script type="application/json" id="data">'''+payload+'''</script><script>'''+script+'''</script></html>'''
